		height = window.innerHeight;
		constructor() {
			let e = () => {
				(this.width = window.innerWidth), (this.height = window.innerHeight);
			};
			window.addEventListener(`resize`, e, !1),
				window.addEventListener(`orientationchange`, e, !1);
		}
		get aspect() {
			return this.width / this.height;
		}
